}
```

```javascript
$(".chat-container").scrollTop($(".chat-container")[0].scrollHeight);
```

### 三、获取元素到浏览器顶部的距离

```javascript
// 原生 JS
var mTop = document.getElementsByClassName('mdiv')[0].offsetTop;
var sTop = document.body.scrollTop;
var result = mTop - sTop;

// jQuery
mTop = $('.mdiv')[0].offsetTop;
sTop = $(window).scrollTop();
result = mTop - sTop;
```

### 四、监听 H5 运行在前台还是后台

```javascript
const audio = document.getElementById('audio');

document.addEventListener('visibilitychange', function (e) {
  if (audio) {
    if (e.currentTarget.hidden) {
      audio.pause();
    } else if (self.state.isPlayMusic) {
      audio.play();
    }
  }
}, true);
```

### 五、解决 iOS12 微信上键盘收起后页面不滑动的问题

```javascript
function isIos12() {
  const ua = navigator.userAgent.toLowerCase();
  const osReg = /iphone|ipad/;
  const versionReg = /os (\d+)_/;
  if (!ua.match(osReg)) return false;
  return Number(ua.match(versionReg)[1]) === 12;
}

function scrollPage() {
  if (isIos12()) {
    const pageTop = $(window).scrollTop();
    window.scrollTo(0, pageTop + 1);
  }
}
```

### 六、在控制台使用 document.designMode 帮助调试

在控制台执行 `document.designMode = 'on'`，之后就可以自由编辑页面里的元素了。

